args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?deathDateFinal WHERE {
  VALUES ?film { dbr:Pacific_Rendezvous dbr:Calling_Bulldog_Drummond }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:deathDate ?deathDate1 . }
  OPTIONAL { ?director dbp:death_date ?deathDate2 . }
  BIND(coalesce(?deathDate1, ?deathDate2) AS ?deathDateFinal)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = 'en') }
} ORDER BY ?film ?directorLabel

